@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IM+Fell+English:ital@0;1&display=swap');
:root{--bg:#10100f;--panel:#171716;--panel2:#1d1d1b;--line:#2c2c28;--text:#e9e5db;--muted:#85847c;--gold:#c5a36d;--gold2:#e1c48f;--rust:#bb6d56;--green:#9aa77a;--serif:'IM Fell English',Georgia,serif;--sans:'DM Sans',system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);font-size:13px}button,a{font:inherit;color:inherit}button{cursor:pointer}.app-shell{min-height:100vh}.sidebar{width:242px;position:fixed;inset:0 auto 0 0;background:#141413;border-right:1px solid #252522;padding:24px 17px 18px;display:flex;flex-direction:column;z-index:5}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;padding:0 6px 26px}.brand-mark{font-size:27px;color:var(--gold);line-height:1}.brand-copy{display:grid;gap:3px}.brand-copy b{font-size:10px;letter-spacing:1.55px;font-weight:700}.brand-copy small{color:#77766f;font-size:8px;letter-spacing:1.35px}.campaign-label{font-size:8px;letter-spacing:1.5px;color:#8e8d84;padding:16px 8px 11px;border-top:1px solid #292926}.live-dot,.save-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a2a57a;margin-right:8px;vertical-align:1px;box-shadow:0 0 8px #a2a57a55}.character-card{display:flex;align-items:center;padding:11px 9px;background:#1c1c19;border:1px solid #292925;border-radius:5px;gap:10px}.avatar{width:34px;height:34px;display:grid;place-items:center;border:1px solid #6b5b40;border-radius:50%;background:radial-gradient(circle at 30% 25%,#716046,#2e2c25 65%);color:#e4c990;font-family:var(--serif);font-size:18px}.character-meta{display:grid;gap:4px;flex:1}.character-meta strong{font-size:12px;font-weight:600}.character-meta span{font-size:10px;color:#95938a}.icon-button{width:30px;height:30px;border:1px solid transparent;background:transparent;color:#99978e;border-radius:4px;font-size:17px}.icon-button:hover{background:#242420;color:var(--gold2)}.edit-name{font-size:14px}.level-track{padding:17px 4px 24px}.level-track>div:first-child{display:flex;justify-content:space-between;color:#87867d;font-size:8px;letter-spacing:1px}.level-track>div:first-child span+span{letter-spacing:0;font-size:9px}.track{height:3px;margin-top:8px;background:#33322d;border-radius:5px;overflow:hidden}.track i{display:block;width:12%;height:100%;background:var(--gold);transition:width .3s}.side-nav{display:grid;gap:4px}.nav-item{height:39px;border:0;text-align:left;background:transparent;color:#a6a49b;border-radius:4px;padding:0 11px;display:flex;align-items:center;gap:12px;font-size:12px}.nav-item>span{font-size:17px;width:17px;text-align:center;color:#8d8a80}.nav-item:hover,.nav-item.active{color:#e5ddcb;background:#24231f}.nav-item.active>span{color:var(--gold)}.nav-item kbd{font-size:8px;margin-left:auto;background:#353229;color:var(--gold2);padding:3px 6px;border-radius:2px}.nav-count{margin-left:auto;color:#a29c88;font-weight:500;font-size:10px}.sidebar-bottom{margin-top:auto}.season-card{display:flex;gap:10px;align-items:center;border-top:1px solid #2a2a26;border-bottom:1px solid #2a2a26;padding:14px 5px}.season-icon{color:#c6a575;font-size:19px;width:26px;text-align:center}.season-card div+div{display:grid;gap:5px}.season-card b{font-weight:500;font-size:10px}.season-card small{font-size:9px;color:#85847b}.reset-button{display:flex;gap:10px;align-items:center;background:none;border:0;color:#9c9a90;padding:13px 7px;font-size:12px}.reset-button:hover{color:var(--gold2)}.autosave{font-size:9px;color:#73736b;padding:6px 7px 0}.save-dot{width:5px;height:5px;background:#7d9575}.main-area{margin-left:242px;min-height:100vh;max-width:1800px}.topbar{height:56px;border-bottom:1px solid #292926;display:flex;align-items:center;justify-content:space-between;padding:0 35px;background:#111110}.breadcrumb{display:flex;align-items:center;gap:10px;font-size:9px;letter-spacing:1.4px;color:#75746d}.breadcrumb i{font-style:normal;color:#4c4a43;font-size:16px}.breadcrumb b{font-size:9px;color:#c5bda9;letter-spacing:1px}.top-actions{display:flex;align-items:center;gap:18px}.weather{font-size:10px;color:#9c9b91}.weather span{font-size:15px;margin-right:5px}.weather i{color:#68665f;font-style:normal;padding:0 3px}.mini-avatar{width:27px;height:27px;font-size:13px}.mobile-menu{display:none}.view{display:none}.view.active{display:block}.world-hero{height:330px;position:relative;overflow:hidden;background:#272823}.hero-image{position:absolute;inset:0;background-image:linear-gradient(90deg,rgba(15,16,14,.91) 0%,rgba(17,18,16,.68) 43%,rgba(17,18,16,.12) 100%),linear-gradient(0deg,#10100f 0%,transparent 35%),url('https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1800&q=85');background-size:cover;background-position:center 55%;filter:saturate(.6)}.hero-shade{position:absolute;inset:0;background:linear-gradient(90deg,transparent 55%,rgba(13,14,12,.12)),linear-gradient(0deg,rgba(16,16,15,.55),transparent 40%);pointer-events:none}.hero-content{position:absolute;left:5.2%;top:42px;width:min(510px,60%)}.eyebrow{display:flex;align-items:center;gap:9px;color:#c1a77b;font-size:8px;letter-spacing:2px;font-weight:700}.eyebrow-line{width:20px;height:1px;background:#b69a68}.tag{border:1px solid #8a7958;color:#d0bb92;padding:4px 7px;font-size:7px;letter-spacing:1px;margin-left:3px}.hero-content h1,.subview-header h1{font-family:var(--serif);font-weight:400;font-size:42px;line-height:1.02;letter-spacing:-.3px;margin:17px 0 12px;color:#f0ece2}.hero-content h1 em,.subview-header h1 em{font-weight:400;color:#d1b887}.hero-content p{font-size:11px;line-height:1.8;color:#cfcdc3;max-width:425px;margin:0}.hero-meta{display:flex;gap:18px;margin-top:21px;color:#b1aea2;font-size:9px}.hero-meta span:first-child{color:#ddc697}.hero-coordinate{position:absolute;bottom:20px;right:27px;font-size:8px;letter-spacing:1.4px;color:#b4b1a6}.hero-coordinate span{color:#c7a773;padding:0 5px}.map-open{position:absolute;right:28px;top:23px;background:#171815c9;border:1px solid #77705d;color:#ded6c5;border-radius:3px;padding:8px 12px;font-size:10px}.map-open span{color:var(--gold2);margin-right:5px}.world-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:27px;padding:25px 35px 48px;max-width:1500px;margin:0 auto}.story-column{min-width:0}.section-heading{display:flex;justify-content:space-between;align-items:end;margin:0 0 14px}.section-kicker{display:block;color:#a99066;font-size:8px;letter-spacing:1.7px;font-weight:700}.section-heading h2,.modal-head h2{font-family:var(--serif);font-size:23px;font-weight:400;margin:4px 0 0;letter-spacing:.1px}.turn-label{font-size:8px;letter-spacing:1.3px;color:#7a7971;padding-bottom:5px}.story-feed{display:grid;gap:10px}.story-entry{position:relative;border:1px solid #282824;border-radius:3px;background:#151514;padding:15px 17px 15px 43px;animation:fadein .3s ease}.story-entry:before{content:'';position:absolute;left:21px;top:20px;bottom:-11px;width:1px;background:#36332a}.story-entry:last-child:before{bottom:22px}.story-entry:after{content:'';position:absolute;left:17px;top:18px;width:8px;height:8px;border:1px solid #b29868;background:#171716;border-radius:50%;box-shadow:0 0 0 3px #171716}.story-entry .entry-time{font-size:8px;letter-spacing:1px;color:#77766e;margin-bottom:7px}.story-entry p{margin:0;color:#c6c3b9;font-size:11px;line-height:1.8}.story-entry p strong{color:#e1d4b8;font-weight:600}.story-entry .entry-result{margin-top:9px;color:#b6a276;font-size:9px}.story-entry.system-entry{border-color:#443d2d;background:linear-gradient(110deg,#1c1a16,#151514)}.story-entry.system-entry:after{background:#c1a16b}.action-box{margin-top:15px;border:1px solid #36342e;border-radius:4px;background:#191918;overflow:hidden;box-shadow:0 5px 25px #0002}.action-top{height:36px;border-bottom:1px solid #2c2c27;display:flex;align-items:center;padding:0 13px;gap:8px;font-size:10px;color:#d0c9b9}.action-icon{color:var(--gold);font-size:15px}.free-action{margin-left:auto;font-size:7px;letter-spacing:1.2px;color:#8e8b7e;border:1px solid #39372f;padding:4px 6px}.action-box textarea{display:block;resize:vertical;min-height:58px;width:100%;padding:12px 14px;background:transparent;border:0;outline:0;color:#e5dfd2;font:11px/1.6 var(--sans)}.action-box textarea::placeholder{color:#77766e}.action-footer{display:flex;align-items:center;justify-content:space-between;padding:0 11px 10px}.hint{font-size:8px;color:#77766e}.hint kbd{border:1px solid #444239;border-radius:2px;padding:2px 4px;color:#aaa699;font:8px var(--sans)}.send-button{background:#9e8053;color:#161510;border:0;border-radius:3px;padding:7px 13px;font-size:10px;font-weight:700;transition:.15s}.send-button:hover{background:#d0b27e;transform:translateY(-1px)}.send-button span{font-size:13px;margin-left:6px}.right-rail{display:grid;align-content:start;gap:11px}.rail-card{background:#171716;border:1px solid #292925;border-radius:4px;padding:14px}.rail-title{display:flex;align-items:center;justify-content:space-between;color:#a9a69a;letter-spacing:1.4px;font-size:8px;font-weight:700}.dots{border:0;background:none;color:#77766e;font-size:17px;letter-spacing:1px;line-height:10px}.vitals{display:grid;gap:13px;margin:17px 0 16px}.vital-row{display:flex;gap:10px;align-items:center}.vital-symbol{width:19px;text-align:center;font-size:13px}.heart{color:#bd7461}.spark{color:#ba9d67}.vital-info{flex:1}.vital-info>div:first-child{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.vital-info b{font-size:10px;font-weight:500;color:#d0cdc3}.vital-info small{font-size:9px;color:#99978c}.vital-track{height:3px;background:#36342f;border-radius:3px;overflow:hidden}.vital-track i{height:100%;display:block;background:#b36b5a;width:100%;transition:width .3s}.vital-track .stamina{background:#b49a63}.stat-grid{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid #2c2c28;border-bottom:1px solid #2c2c28}.stat-grid>div{padding:11px 3px;display:grid;gap:5px}.stat-grid>div:nth-child(odd){border-right:1px solid #2c2c28}.stat-grid>div:nth-child(even){padding-left:12px}.stat-grid>div:nth-child(n+3){border-top:1px solid #2c2c28}.stat-grid small{font-size:7px;color:#858379;letter-spacing:1.1px}.stat-grid b{font-size:10px;color:#ddd7c9;font-weight:500}.stat-grid b:first-letter{color:#d1ad71}.inventory-line{display:flex;align-items:center;gap:7px;padding-top:12px;color:#99978d;font-size:9px}.inventory-line>span{font-size:14px;color:#bb9d68}.inventory-line b{font-weight:500;color:#c8c3b7}.inventory-line>span+ b{margin-right:auto}.inventory-line button,.text-link{background:none;border:0;color:#b8a77f;font-size:9px;padding:0}.text-link:hover,.inventory-line button:hover{color:#e4c790}.quest-card{padding:14px 13px 7px}.quest-card .rail-title{padding:0 1px 5px}.quest-mini{padding:11px 0;border-bottom:1px solid #292925;display:grid;grid-template-columns:7px 1fr;gap:9px}.quest-mini:last-child{border-bottom:0}.quest-pin{width:5px;height:5px;border:1px solid #bd9d69;border-radius:50%;margin-top:4px}.quest-mini b{font-size:10px;display:block;font-weight:500;color:#d6d0c3}.quest-mini small{display:block;color:#848279;font-size:9px;margin-top:4px;line-height:1.45}.quest-mini .quest-kind{font-size:7px;color:#b49b6a;letter-spacing:.7px;margin-bottom:4px}.omen-card{position:relative;display:flex;gap:10px;padding:13px 13px 12px;border:1px solid #383126;background:linear-gradient(120deg,#211e19,#171716);overflow:hidden}.omen-mark{font:30px var(--serif);color:#ad9061;line-height:1}.omen-card>div:nth-child(2){z-index:1}.omen-card span{font-size:7px;letter-spacing:1.3px;color:#b69b6b}.omen-card p{font:italic 12px/1.5 var(--serif);color:#c9c0ad;margin:5px 0 0}.omen-flourish{position:absolute;right:7px;bottom:-17px;font-size:61px;color:#8c70442a}.people-card{background:#171716;border:1px solid #292925;border-radius:4px;padding:13px}.people-card .rail-title{margin-bottom:5px}.person-row{display:flex;align-items:center;gap:9px;padding:8px 0 4px}.person-avatar{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#343129;color:#c1a575;font-family:var(--serif);font-size:14px;border:1px solid #494130}.person-info{display:grid;gap:3px;flex:1}.person-info b{font-size:9px;font-weight:500}.person-info small{font-size:8px;color:#848279}.person-attitude{font-size:8px;color:#a99b79}.footer-note{text-align:center;color:#55544d;font-size:7px;letter-spacing:2px;padding:0 0 18px}.footer-note span{color:#9c8058;padding:0 5px}.subview{padding:49px 5.2% 60px;min-height:calc(100vh - 57px)}.subview-header{border-bottom:1px solid #2b2a25;padding-bottom:25px;margin-bottom:24px}.subview-header h1{font-size:39px;margin:13px 0 8px}.subview-header p{margin:0;color:#96948a;font-size:11px}.journal-grid,.codex-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;max-width:1000px}.journal-card,.codex-card{background:#171716;border:1px solid #2d2c27;padding:17px;border-radius:3px}.journal-card h3,.codex-card h3{font:20px var(--serif);margin:7px 0;color:#e2d9c8}.journal-card p,.codex-card p{font-size:10px;line-height:1.8;color:#a7a49a}.journal-card .eyebrow,.codex-card .eyebrow{font-size:7px}.journal-state{font-size:8px;letter-spacing:1px;color:#b09a6c}.codex-region{min-height:150px;position:relative;overflow:hidden}.codex-region:after{content:'✧';position:absolute;right:12px;top:10px;font-size:55px;color:#a9875130}.codex-card .region-name{font-size:8px;letter-spacing:1.5px;color:#b69a68}.map-overlay{display:none;position:fixed;inset:0;background:#050504c9;z-index:20;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(5px)}.map-overlay.open{display:flex}.map-panel{width:min(760px,100%);background:#171715;border:1px solid #514936;border-radius:5px;padding:25px;box-shadow:0 20px 90px #0009;max-height:90vh;overflow:auto;animation:fadein .2s}.modal-head{display:flex;align-items:start;justify-content:space-between}.modal-head h2{font-size:25px;margin-top:6px}.modal-head h2 em{color:#cbb184;font-weight:400}.close-map{border:1px solid #3d3b34;font-size:21px}.map-intro{font-size:10px;color:#9e9b91;margin:12px 0 18px}.region-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.region-card{min-height:115px;text-align:left;padding:13px;border:1px solid #36342d;background:linear-gradient(145deg,#22211d,#191917);border-radius:3px;position:relative;overflow:hidden}.region-card:hover:not(:disabled){border-color:#a48b60;background:#26231d}.region-card:disabled{opacity:.52;cursor:not-allowed}.region-card .region-symbol{font-size:17px;color:#c0a472}.region-card b{display:block;font:18px var(--serif);margin:5px 0}.region-card small{display:block;color:#96938a;font-size:8px;line-height:1.5}.region-card .region-status{position:absolute;right:10px;top:12px;font-size:7px;letter-spacing:.8px;color:#a7a084}.map-legend{display:flex;gap:18px;margin-top:17px;color:#89877e;font-size:8px}.legend-dot{width:6px;height:6px;border-radius:50%;display:inline-block;margin-right:5px;background:#a89065}.legend-dot.open{background:#777d69}.legend-dot.veil{background:#494943}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);padding:10px 15px;border:1px solid #63543b;border-radius:3px;background:#211e18;color:#e2d4b8;font-size:10px;opacity:0;pointer-events:none;transition:.25s;z-index:30}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes fadein{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
@media(min-width:1500px){.world-hero{height:370px}.world-layout{padding-top:30px;grid-template-columns:minmax(0,1fr) 320px}.hero-content{top:54px}.hero-content h1{font-size:49px}}
@media(max-width:1050px){.sidebar{width:210px;padding-left:13px;padding-right:13px}.main-area{margin-left:210px}.world-layout{grid-template-columns:minmax(0,1fr) 260px;gap:16px;padding-left:23px;padding-right:23px}.hero-content{left:4.5%}.hero-image{background-position:58% center}.topbar{padding:0 23px}}
@media(max-width:780px){.sidebar{transform:translateX(-100%);transition:transform .25s;box-shadow:10px 0 40px #0008}.sidebar.open{transform:translateX(0)}.main-area{margin-left:0}.topbar{height:51px;padding:0 14px}.mobile-menu{display:block;margin-left:-7px}.breadcrumb{margin-right:auto;margin-left:6px;font-size:8px;gap:7px}.top-actions{gap:10px}.weather{font-size:9px}.world-hero{height:340px}.hero-content{left:22px;top:46px;width:75%}.hero-content h1{font-size:37px}.hero-content p{font-size:10px;max-width:370px}.hero-meta{gap:11px;font-size:8px;flex-wrap:wrap}.hero-coordinate{font-size:7px;right:14px;bottom:14px}.map-open{right:13px;top:13px;padding:7px 9px}.world-layout{display:flex;flex-direction:column;padding:23px 16px 38px;gap:22px}.right-rail{grid-template-columns:1fr 1fr;align-items:start}.status-card{grid-column:1/-1}.quest-card,.people-card,.omen-card{min-width:0}.section-heading h2{font-size:22px}.footer-note{padding:12px 0 22px}.subview{padding:35px 18px 50px}.subview-header h1{font-size:34px}.journal-grid,.codex-grid{grid-template-columns:1fr}}
@media(max-width:480px){.world-hero{height:365px}.hero-content{top:51px;width:calc(100% - 35px)}.hero-content h1{font-size:35px;margin-top:16px}.hero-content p{line-height:1.7}.hero-meta{max-width:275px;row-gap:7px}.hero-meta span:last-child{display:none}.world-layout{padding-top:20px}.right-rail{grid-template-columns:1fr}.status-card{grid-column:auto}.omen-card{order:2}.quest-card{order:1}.people-card{order:3}.hint{max-width:190px;line-height:1.5}.region-grid{grid-template-columns:1fr 1fr}.map-panel{padding:19px}.map-legend{flex-wrap:wrap;gap:9px}.turn-label{font-size:7px}.story-entry{padding:13px 13px 13px 38px}.story-entry:before{left:18px}.story-entry:after{left:14px}}

(() => {
  const SAVE_KEY = 'ecos-destino-save-v1';
  const regions = [
    {id:'valtherion',name:'Valtherion',city:'Brumafria',title:'Vale de Cinzas',label:'VALE DE CINZAS',tone:'Reino humano · comércio, intrigas e guerras de sucessão.',symbol:'♜',travel:0,desc:'A estrada de pedra desce entre colinas cobertas de névoa. Ao longe, a vila de Brumafria acende suas primeiras lanternas — pequenas brasas contra uma noite que parece observar você.',culture:'Humana, pragmática e dividida entre juramentos feudais.',religion:'A Chama Perene, que promete manter os mortos em repouso.',conflict:'A Casa Veyne disputa o trono com os barões do norte.',creatures:'Corvos-de-ferrugem, cães selvagens e espectros de estrada.',secret:'Nas fundações da velha capela, sinos tocam quando ninguém os puxa.',faction:'Companhia do Veado Negro',economy:'Ferro, lã e vinho escuro',event:'Um cobrador real desapareceu na estrada, levando os impostos da colheita.'},
